unpack(): CVPT {
  return new CVPT(
    this.COVERAGE_ID(),
    this.NAME(),
    this.SCENARIO_ID(),
    this.GEOMETRY_KIND(),
    this.METRIC(),
    this.METRIC_UNITS(),
    this.THRESHOLD_VALUE(),
    this.THRESHOLD_UNITS(),
    this.THRESHOLD_COMPARISON(),
    this.EPOCH(),
    this.INTERVAL_START(),
    this.INTERVAL_STOP(),
    this.TIME_SYSTEM(),
    this.GENERATION(),
    this.SUPERSEDES_COVERAGE_ID(),
    this.bb!.createScalarList<number>(this.VERTEX_LONGITUDE_DEG.bind(this), this.vertexLongitudeDegLength()),
    this.bb!.createScalarList<number>(this.VERTEX_LATITUDE_DEG.bind(this), this.vertexLatitudeDegLength()),
    this.bb!.createScalarList<number>(this.VERTEX_ALTITUDE_M.bind(this), this.vertexAltitudeMLength()),
    this.ALTITUDE_REFERENCE(),
    this.FIXED_ALTITUDE_M(),
    this.bb!.createScalarList<number>(this.RING_OFFSETS.bind(this), this.ringOffsetsLength()),
    this.bb!.createScalarList<number>(this.RING_POLYGON_INDEXES.bind(this), this.ringPolygonIndexesLength()),
    this.bb!.createScalarList<cvpRingRole>(this.RING_ROLES.bind(this), this.ringRolesLength()),
    this.POLYGON_COUNT(),
    this.bb!.createScalarList<number>(this.POLYGON_LEVEL_VALUES.bind(this), this.polygonLevelValuesLength()),
    this.bb!.createScalarList<number>(this.POLYGON_LEVEL_UNCERTAINTIES.bind(this), this.polygonLevelUncertaintiesLength()),
    this.bb!.createScalarList<number>(this.POLYGON_AREA_KM2.bind(this), this.polygonAreaKm2Length()),
    this.bb!.createScalarList<number>(this.VERTEX_POSITION_UNCERTAINTY_M.bind(this), this.vertexPositionUncertaintyMLength()),
    this.GRID_SCHEME(),
    this.GRID_RESOLUTION(),
    this.GRID_SPACING_DEG(),
    this.GRID_CELL_COUNT(),
    this.CVG_COVERAGE_ID(),
    this.RFL_ID(),
    this.ACI_ID(),
    this.bb!.createObjList<CVPEmitterRef, CVPEmitterRefT>(this.CONTRIBUTING_EMITTERS.bind(this), this.contributingEmittersLength()),
    this.RECEIVER_SET_ID(),
    this.bb!.createObjList<CVPReceiverRef, CVPReceiverRefT>(this.RECEIVERS.bind(this), this.receiversLength()),
    this.bb!.createObjList<CVPObstacleRef, CVPObstacleRefT>(this.CONTRIBUTING_OBSTACLES.bind(this), this.contributingObstaclesLength()),
    this.OBSTACLE_SET_ID(),
    this.LIMITING_CONSTRAINT(),
    this.LIMITING_CONSTRAINT_NOTE(),
    (this.UNCERTAINTY() !== null ? this.UNCERTAINTY()!.unpack() : null),
    (this.PROVENANCE() !== null ? this.PROVENANCE()!.unpack() : null),
    this.COMPUTED_AT(),
    this.PRODUCER_ID(),
    this.bb!.createScalarList<number>(this.SIGNATURE.bind(this), this.signatureLength())
  );
}


